diff --git a/src/runner/dependency.rs b/src/runner/dependency.rs
index 872fd69..00d7c30 100644
--- a/src/runner/dependency.rs
+++ b/src/runner/dependency.rs
@@ -688,4 +688,344 @@ mod tests {

         assert!(skipped.is_empty());
     }
+
+    // --- Circular reference tests ---
+
+    #[test]
+    fn transitive_dependents_two_node_cycle_terminates() {
+        let graph = DependencyGraph::builder()
+            .add_step("a", vec!["b".to_string()])
+            .add_step("b", vec!["a".to_string()])
+            .build()
+            .unwrap();
+
+        // Must terminate without infinite loop
+        let deps = graph.transitive_dependents("a");
+        assert!(deps.contains("b"));
+    }
+
+    #[test]
+    fn transitive_dependents_three_node_cycle_terminates() {
+        let graph = DependencyGraph::builder()
+            .add_step("a", vec!["c".to_string()])
+            .add_step("b", vec!["a".to_string()])
+            .add_step("c", vec!["b".to_string()])
+            .build()
+            .unwrap();
+
+        let deps = graph.transitive_dependents("a");
+        assert!(deps.contains("b"));
+        assert!(deps.contains("c"));
+    }
+
+    #[test]
+    fn transitive_dependents_self_cycle_terminates() {
+        let graph = DependencyGraph::builder()
+            .add_step("a", vec!["a".to_string()])
+            .build()
+            .unwrap();
+
+        // "a" depends on itself; transitive_dependents follows the
+        // reverse (dependents) edges. "a" is a dependent of itself,
+        // so it should appear in the result and the traversal must stop.
+        let deps = graph.transitive_dependents("a");
+        assert!(deps.contains("a"));
+    }
+
+    #[test]
+    fn compute_skips_with_dependents_on_cyclic_graph_terminates() {
+        let graph = DependencyGraph::builder()
+            .add_step("a", vec!["b".to_string()])
+            .add_step("b", vec!["a".to_string()])
+            .add_step("c", vec!["b".to_string()])
+            .build()
+            .unwrap();
+
+        let mut skip = HashSet::new();
+        skip.insert("a".to_string());
+
+        // Must terminate and cascade to all reachable dependents
+        let skipped = graph.compute_skips(&skip, SkipBehavior::SkipWithDependents);
+        assert!(skipped.contains("a"));
+        assert!(skipped.contains("b"));
+        assert!(skipped.contains("c"));
+    }
+
+    #[test]
+    fn parallel_groups_rejects_cycle() {
+        let graph = DependencyGraph::builder()
+            .add_step("a", vec!["b".to_string()])
+            .add_step("b", vec!["a".to_string()])
+            .build()
+            .unwrap();
+
+        let result = graph.parallel_groups();
+        assert!(result.is_err());
+    }
+
+    #[test]
+    fn topological_order_detects_self_cycle() {
+        let graph = DependencyGraph::builder()
+            .add_step("a", vec!["a".to_string()])
+            .build()
+            .unwrap();
+
+        let result = graph.topological_order();
+        assert!(result.is_err());
+    }
+
+    #[test]
+    fn topological_order_detects_three_node_cycle() {
+        let graph = DependencyGraph::builder()
+            .add_step("a", vec!["c".to_string()])
+            .add_step("b", vec!["a".to_string()])
+            .add_step("c", vec!["b".to_string()])
+            .build()
+            .unwrap();
+
+        let result = graph.topological_order();
+        assert!(result.is_err());
+    }
+
+    #[test]
+    fn find_cycle_on_empty_graph_returns_none() {
+        let graph = DependencyGraph::builder().build().unwrap();
+        assert!(graph.find_cycle().is_none());
+    }
+
+    #[test]
+    fn parallel_groups_rejects_three_node_cycle() {
+        let graph = DependencyGraph::builder()
+            .add_step("a", vec!["c".to_string()])
+            .add_step("b", vec!["a".to_string()])
+            .add_step("c", vec!["b".to_string()])
+            .build()
+            .unwrap();
+
+        let result = graph.parallel_groups();
+        assert!(result.is_err());
+    }
+
+    #[test]
+    fn is_ready_with_cycle_never_satisfied() {
+        let graph = DependencyGraph::builder()
+            .add_step("a", vec!["b".to_string()])
+            .add_step("b", vec!["a".to_string()])
+            .build()
+            .unwrap();
+
+        // Neither step can ever be ready because each depends on the other
+        assert!(!graph.is_ready("a", &HashSet::new()));
+        assert!(!graph.is_ready("b", &HashSet::new()));
+    }
+
+    // --- Accessor edge case tests ---
+
+    #[test]
+    fn dependencies_of_unknown_step_returns_none() {
+        let graph = DependencyGraph::builder()
+            .add_step("a", vec![])
+            .build()
+            .unwrap();
+
+        assert!(graph.dependencies_of("nonexistent").is_none());
+    }
+
+    #[test]
+    fn dependents_of_unknown_step_returns_none() {
+        let graph = DependencyGraph::builder()
+            .add_step("a", vec![])
+            .build()
+            .unwrap();
+
+        assert!(graph.dependents_of("nonexistent").is_none());
+    }
+
+    #[test]
+    fn contains_returns_false_for_unknown_step() {
+        let graph = DependencyGraph::builder()
+            .add_step("a", vec![])
+            .build()
+            .unwrap();
+
+        assert!(!graph.contains("nonexistent"));
+    }
+
+    #[test]
+    fn steps_returns_all_step_names() {
+        let graph = DependencyGraph::builder()
+            .add_step("a", vec![])
+            .add_step("b", vec!["a".to_string()])
+            .add_step("c", vec![])
+            .build()
+            .unwrap();
+
+        let steps = graph.steps();
+        assert_eq!(steps.len(), 3);
+        assert!(steps.contains("a"));
+        assert!(steps.contains("b"));
+        assert!(steps.contains("c"));
+    }
+
+    #[test]
+    fn len_returns_correct_count() {
+        let graph = DependencyGraph::builder()
+            .add_step("a", vec![])
+            .add_step("b", vec![])
+            .build()
+            .unwrap();
+
+        assert_eq!(graph.len(), 2);
+    }
+
+    #[test]
+    fn is_empty_returns_false_for_nonempty_graph() {
+        let graph = DependencyGraph::builder()
+            .add_step("a", vec![])
+            .build()
+            .unwrap();
+
+        assert!(!graph.is_empty());
+    }
+
+    #[test]
+    fn is_ready_for_unknown_step_returns_true() {
+        let graph = DependencyGraph::builder()
+            .add_step("a", vec![])
+            .build()
+            .unwrap();
+
+        // Unknown step has no entry in the dependencies map, so is_ready returns true
+        assert!(graph.is_ready("unknown", &HashSet::new()));
+    }
+
+    #[test]
+    fn transitive_dependents_of_unknown_step_returns_empty() {
+        let graph = DependencyGraph::builder()
+            .add_step("a", vec![])
+            .build()
+            .unwrap();
+
+        let deps = graph.transitive_dependents("unknown");
+        assert!(deps.is_empty());
+    }
+
+    #[test]
+    fn builder_merges_dependencies_for_same_step() {
+        let graph = DependencyGraph::builder()
+            .add_step("a", vec![])
+            .add_step("b", vec![])
+            .add_step("c", vec!["a".to_string()])
+            .add_step("c", vec!["b".to_string()])
+            .build()
+            .unwrap();
+
+        let deps = graph.dependencies_of("c").unwrap();
+        assert!(deps.contains("a"));
+        assert!(deps.contains("b"));
+    }
+
+    #[test]
+    fn skip_behavior_default_is_skip_with_dependents() {
+        assert_eq!(SkipBehavior::default(), SkipBehavior::SkipWithDependents);
+    }
+
+    #[test]
+    fn topological_order_cycle_error_lists_involved_steps() {
+        let graph = DependencyGraph::builder()
+            .add_step("a", vec!["b".to_string()])
+            .add_step("b", vec!["a".to_string()])
+            .add_step("c", vec![])
+            .build()
+            .unwrap();
+
+        let err = graph.topological_order().unwrap_err();
+        let msg = err.to_string();
+        // The error should mention the cycling steps, not the uninvolved "c"
+        assert!(msg.contains("a") || msg.contains("b"));
+    }
+
+    #[test]
+    fn find_cycle_path_forms_closed_loop() {
+        let graph = DependencyGraph::builder()
+            .add_step("x", vec!["z".to_string()])
+            .add_step("y", vec!["x".to_string()])
+            .add_step("z", vec!["y".to_string()])
+            .build()
+            .unwrap();
+
+        let cycle = graph.find_cycle().unwrap();
+        // A valid cycle path starts and ends with the same node
+        assert_eq!(cycle.first(), cycle.last());
+        assert!(cycle.len() >= 3); // at least 2 distinct nodes + closing node
+    }
+
+    #[test]
+    fn parallel_groups_mixed_cycle_and_independent() {
+        // Graph has an independent step "c" and a cycle between "a" and "b"
+        let graph = DependencyGraph::builder()
+            .add_step("a", vec!["b".to_string()])
+            .add_step("b", vec!["a".to_string()])
+            .add_step("c", vec![])
+            .build()
+            .unwrap();
+
+        // Even though "c" is independent, the cycle should cause an error
+        let result = graph.parallel_groups();
+        assert!(result.is_err());
+    }
+
+    #[test]
+    fn compute_skips_with_dependents_does_not_include_unrelated() {
+        let graph = DependencyGraph::builder()
+            .add_step("a", vec![])
+            .add_step("b", vec!["a".to_string()])
+            .add_step("c", vec![])
+            .build()
+            .unwrap();
+
+        let mut skip = HashSet::new();
+        skip.insert("a".to_string());
+
+        let skipped = graph.compute_skips(&skip, SkipBehavior::SkipWithDependents);
+        assert!(skipped.contains("a"));
+        assert!(skipped.contains("b"));
+        assert!(!skipped.contains("c"));
+    }
+
+    #[test]
+    fn transitive_dependents_diamond_collects_all() {
+        let graph = DependencyGraph::builder()
+            .add_step("root", vec![])
+            .add_step("left", vec!["root".to_string()])
+            .add_step("right", vec!["root".to_string()])
+            .add_step("bottom", vec!["left".to_string(), "right".to_string()])
+            .build()
+            .unwrap();
+
+        let deps = graph.transitive_dependents("root");
+        assert!(deps.contains("left"));
+        assert!(deps.contains("right"));
+        assert!(deps.contains("bottom"));
+        assert!(!deps.contains("root"));
+    }
+
+    #[test]
+    fn is_ready_partial_dependencies_met() {
+        let graph = DependencyGraph::builder()
+            .add_step("a", vec![])
+            .add_step("b", vec![])
+            .add_step("c", vec!["a".to_string(), "b".to_string()])
+            .build()
+            .unwrap();
+
+        let mut completed = HashSet::new();
+        completed.insert("a".to_string());
+
+        // Only one of two deps met
+        assert!(!graph.is_ready("c", &completed));
+
+        completed.insert("b".to_string());
+        assert!(graph.is_ready("c", &completed));
+    }
 }

